<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Profile | Digital Library</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="site-header"><a class="brand" href="/dashboard">Digital Library</a><nav><a href="/">Catalog</a><form method="post" action="/logout"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit">Log out</button></form></nav></header><main class="container"><p class="eyebrow">Account settings</p><h1>Your profile</h1><?php if ($error): ?><p class="form-error" role="alert"><?= e($error) ?></p><?php endif; ?><?php if ($success): ?><p class="form-success" role="status"><?= e($success) ?></p><?php endif; ?><form method="post" class="book-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label for="name">Name</label><input id="name" name="name" value="<?= e($user['name']) ?>" required maxlength="120"><label for="email">Email</label><input id="email" name="email" type="email" value="<?= e($user['email']) ?>" required maxlength="190"><label for="current_password">Current password</label><input id="current_password" name="current_password" type="password" autocomplete="current-password"><label for="new_password">New password</label><input id="new_password" name="new_password" type="password" minlength="8" maxlength="4096" autocomplete="new-password"><button type="submit">Save profile</button></form></main></body></html>